import APP_HTML    from './ui/app.html'
import ADMIN_HTML   from './ui/admin.html'
import HARNESS_HTML from './ui/harness.html'

export default {
  async fetch(request, env, ctx) {
    const url  = new URL(request.url)
    const path = url.pathname

    // ── Pages ──
    if (path === '/' || path === '/app')  return htmlResponse(APP_HTML)
    if (path === '/admin')                return htmlResponse(ADMIN_HTML)
    if (path === '/harness')              return htmlResponse(HARNESS_HTML)

    // ── SVG Logos ──
    if (path.startsWith('/assets/logos/') && path.endsWith('.svg')) {
      const key = path.replace('/assets/logos/', '').replace('.svg', '')
      const svg = LOGOS[key]
      if (svg) return new Response(svg, {
        headers: { 'Content-Type': 'image/svg+xml', 'Cache-Control': 'public, max-age=86400' }
      })
    }

    // ── Data APIs ──
    if (path === '/api/config')             return handleConfig(request, env)
    if (path === '/api/lookup')             return handleLookup(request, env)
    if (path === '/api/customer/update')    return handleCustomerUpdate(request, env)
    if (path === '/api/record/update')      return handleRecordUpdate(request, env)
    if (path === '/api/record/create')      return handleRecordCreate(request, env)

    // ── Admin APIs ──
    if (path === '/api/admin/seed')         return handleSeed(request, env)
    if (path === '/api/admin/reset-all')    return handleResetAll(request, env)
    if (path === '/api/admin/config')       return handleAdminConfigUpdate(request, env)
    if (path === '/api/admin/seeds')        return handleAdminSeedsList(request, env)
    if (path === '/api/admin/seeds/add')    return handleAdminSeedAdd(request, env)
    if (path === '/api/admin/seeds/delete') return handleAdminSeedDelete(request, env)
    if (path === '/api/lookup/select')      return handleLookupSelect(request, env)

    // ── Debug (remove before go-live) ──
    if (path === '/api/debug/sf')           return handleDebugSalesforce(request, env)

    return new Response('Not found', { status: 404 })
  }
}

