// ─────────────────────────────────────────
// Debug Handler — Salesforce raw lookup
// ─────────────────────────────────────────

async function handleDebugSalesforce(request, env) {
  try {
    const url   = new URL(request.url)
    const phone = url.searchParams.get('phone') || ''
    if (!phone) return Response.json({ error: 'Pass ?phone=+447...' }, { status: 400 })

    const normalized = normalizePhone(phone)
    const p          = escapeSoql(normalized)
    const soql       = `SELECT Id,Name,Email,Phone,MobilePhone,MailingAddress,Status__c,LastModifiedDate FROM Contact WHERE Phone='${p}' OR MobilePhone='${p}' ORDER BY LastModifiedDate DESC LIMIT 1`

    let tokenError = null
    let accessToken = null
    try {
      accessToken = await getSalesforceAccessToken(env)
    } catch (e) {
      tokenError = String(e?.message || e)
    }

    if (tokenError) return Response.json({ normalized, soql, tokenError })

    const result = await salesforceQuery(soql, accessToken, env)
    return Response.json({ normalized, soql, result }, { headers: { 'Content-Type': 'application/json' } })
  } catch (err) {
    return Response.json({ error: String(err?.message || err) }, { status: 500 })
  }
}

// ─────────────────────────────────────────
// API Handlers — Config
// ─────────────────────────────────────────

async function handleConfig(request, env) {
  try {
    const row = await env.DB.prepare(`SELECT * FROM config WHERE id=1 LIMIT 1`).first()
    return Response.json(row ?? {})
  } catch (err) {
    return Response.json({ error: String(err?.message || err) }, { status: 500 })
  }
}

async function handleAdminConfigUpdate(request, env) {
  try {
    if (request.method !== 'POST') return new Response('Method not allowed', { status: 405 })

    const body = await request.json().catch(() => ({}))

    // If a presetKey is given, start from the preset values
    let updates = {}
    if (body.presetKey) {
      updates = { ...getBrandPreset(body.presetKey) }
    }

    // Apply any explicit field overrides from the request body
    const allowed = [
      'brand', 'backend', 'app_title', 'customer_label', 'primary_record_label',
      'create_label', 'recent_records_label', 'customer_tier_label',
      'logo_url', 'primary_hex', 'secondary_hex', 'accent_hex', 'debug',
      'combination_crms'
    ]
    for (const field of allowed) {
      if (body[field] !== undefined) updates[field] = body[field]
    }

    if (Object.keys(updates).length === 0) {
      return Response.json({ error: 'No fields to update' }, { status: 400 })
    }

    const setClauses = Object.keys(updates).map(k => `${k}=?`).join(', ')
    const values = Object.values(updates)

    await env.DB.prepare(`UPDATE config SET ${setClauses}, updated_at=datetime('now') WHERE id=1`)
      .bind(...values).run()

    return Response.json({ ok: true, updates })
  } catch (err) {
    return Response.json({ error: String(err?.message || err) }, { status: 500 })
  }
}

// ─────────────────────────────────────────
// API Handlers — Seeds / Scenarios
// ─────────────────────────────────────────

async function handleAdminSeedsList(request, env) {
  try {
    const seeds = await env.DB.prepare(`SELECT * FROM seeds ORDER BY scenario_key`).all()
    const stateRow = await env.DB.prepare(`SELECT value FROM state WHERE key='active_scenario'`).first()
    return Response.json({
      ok: true,
      seeds: seeds.results || [],
      activeScenario: stateRow?.value || ''
    })
  } catch (err) {
    return Response.json({ error: String(err?.message || err) }, { status: 500 })
  }
}

async function handleAdminSeedAdd(request, env) {
  try {
    if (request.method !== 'POST') return new Response('Method not allowed', { status: 405 })
    const body = await request.json().catch(() => ({}))

    if (!body.scenario_key) return Response.json({ error: 'scenario_key is required' }, { status: 400 })

    await env.DB.prepare(`
      INSERT INTO seeds
        (scenario_key, backend, phone, email, customer_name, customer_status,
         primary_subject, primary_status, primary_due_date, recent_count)
      VALUES (?,?,?,?,?,?,?,?,?,?)
      ON CONFLICT(scenario_key) DO UPDATE SET
        backend=excluded.backend, phone=excluded.phone, email=excluded.email,
        customer_name=excluded.customer_name, customer_status=excluded.customer_status,
        primary_subject=excluded.primary_subject, primary_status=excluded.primary_status,
        primary_due_date=excluded.primary_due_date, recent_count=excluded.recent_count
    `).bind(
      body.scenario_key,
      body.backend          || 'custom_crm',
      body.phone            || '',
      body.email            || '',
      body.customer_name    || '',
      body.customer_status  || '',
      body.primary_subject  || '',
      body.primary_status   || '',
      body.primary_due_date || '',
      Number(body.recent_count) || 0
    ).run()

    return Response.json({ ok: true })
  } catch (err) {
    return Response.json({ error: String(err?.message || err) }, { status: 500 })
  }
}

async function handleAdminSeedDelete(request, env) {
  try {
    if (request.method !== 'POST') return new Response('Method not allowed', { status: 405 })
    const body = await request.json().catch(() => ({}))
    if (!body.scenario_key) return Response.json({ error: 'scenario_key is required' }, { status: 400 })
    await env.DB.prepare(`DELETE FROM seeds WHERE scenario_key=?`).bind(body.scenario_key).run()
    return Response.json({ ok: true })
  } catch (err) {
    return Response.json({ error: String(err?.message || err) }, { status: 500 })
  }
}

// ─────────────────────────────────────────
// API Handlers — Lookup
// ─────────────────────────────────────────

async function handleLookup(request, env) {
  try {
    const body = await request.json().catch(() => ({}))
    const incomingPhone =
      body.phone ||
      body?.variables?.Consumer?.phoneNumber1 ||
      body?.variables?.consumer?.phoneNumber1 ||
      ''
    const incomingEmail = body.email || ''
    const channel       = body.channel || 'voice'
    const variables     = body.variables || {}

    const config = await env.DB.prepare(`SELECT * FROM config WHERE id=1 LIMIT 1`).first()
    const normalizedPhone = normalizePhone(incomingPhone)

    let result
    if (config.brand === 'combination' && config.combination_crms) {
      // Combination mode: look up from each CRM in parallel
      const comboKeys = config.combination_crms.split(',').filter(Boolean)
      const lookupResults = await Promise.all(
        comboKeys.map(key =>
          lookupForBrand(key, { phone: normalizedPhone, email: incomingEmail, env })
            .catch(err => ({ customer: null, primaryRecord: null, recentRecords: [], error: String(err?.message || err) }))
        )
      )
      // Primary CRM (first in list) drives the top-level customer/record fields
      const primaryResult = lookupResults[0] || {}
      const crmResults = {}
      comboKeys.forEach((key, i) => { crmResults[key] = lookupResults[i] })
      result = { ...primaryResult, crmResults }
    } else if (config.backend === 'salesforce') {
      result = await lookupSalesforce({ phone: normalizedPhone, email: incomingEmail, env })
    } else if (config.backend === 'hubspot') {
      result = await lookupHubspot({ phone: normalizedPhone, email: incomingEmail, env })
    } else {
      result = await lookupMockCrm({ phone: normalizedPhone, email: incomingEmail, env })
    }

    return Response.json({
      ok: true,
      config,
      engagement: { channel, phone: incomingPhone, normalizedPhone, email: incomingEmail, variables },
      ...result
    })
  } catch (err) {
    return Response.json({ error: String(err?.message || err) }, { status: 500 })
  }
}

// ─────────────────────────────────────────
// API Handler — Contact Select (multi-match picker)
// ─────────────────────────────────────────

async function handleLookupSelect(request, env) {
  try {
    if (request.method !== 'POST') return new Response('Method not allowed', { status: 405 })
    const body      = await request.json().catch(() => ({}))
    const contactId = body.contactId
    const backend   = body.backend || 'salesforce'
    if (!contactId) return Response.json({ error: 'contactId is required' }, { status: 400 })

    const config = await env.DB.prepare(`SELECT * FROM config WHERE id=1 LIMIT 1`).first()

    let result
    if (backend === 'salesforce') {
      result = await lookupSalesforceByContactId({ contactId, env })
    } else {
      return Response.json({ error: `Select not supported for backend: ${backend}` }, { status: 400 })
    }

    return Response.json({ ok: true, config, ...result })
  } catch (err) {
    return Response.json({ error: String(err?.message || err) }, { status: 500 })
  }
}

// ─────────────────────────────────────────
// API Handlers — Customer & Record Updates
// ─────────────────────────────────────────

async function handleCustomerUpdate(request, env) {
  try {
    if (request.method !== 'POST') return new Response('Method not allowed', { status: 405 })

    const config = await env.DB.prepare(`SELECT * FROM config WHERE id=1 LIMIT 1`).first()
    if (!config) return Response.json({ error: 'No config found' }, { status: 500 })

    const body         = await request.json().catch(() => ({}))
    const customerId   = body.customerId
    const name         = body.name
    const email        = body.email
    const address      = body.address
    const tierOrStatus = body.tierOrStatus

    if (!customerId) return Response.json({ error: 'customerId is required' }, { status: 400 })

    if (config.backend === 'custom_crm') {
      const patchBody = {}
      if (typeof name         === 'string') patchBody.name     = name
      if (typeof email        === 'string') patchBody.email    = email
      if (typeof address      === 'string') patchBody.location = address
      if (typeof tierOrStatus === 'string') patchBody.status   = tierOrStatus

      if (Object.keys(patchBody).length === 0) return Response.json({ error: 'No fields to update' }, { status: 400 })

      const token = env.MOCK_API_TOKEN
      const base  = env.MOCK_API_BASE_URL
      const patchUrl = `${base}/demoapp?token=${encodeURIComponent(token)}&id=${encodeURIComponent(customerId)}`

      const patchRes  = await fetch(patchUrl, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(patchBody)
      })
      const patchData = await patchRes.json().catch(() => ({}))

      if (!patchRes.ok) return Response.json({ error: 'Mock CRM customer update failed', details: patchData }, { status: 500 })
      return Response.json({ ok: true, updated: patchData })
    }

    if (config.backend === 'salesforce') {
      const accessToken = await getSalesforceAccessToken(env)
      const patchBody   = {}

      if (typeof name === 'string' && name.trim()) {
        const parts = name.trim().split(/\s+/)
        if (parts.length === 1) { patchBody.LastName = parts[0] }
        else { patchBody.FirstName = parts.slice(0, -1).join(' '); patchBody.LastName = parts.at(-1) }
      }
      if (typeof email        === 'string') patchBody.Email        = email
      if (typeof tierOrStatus === 'string') patchBody.Status__c    = tierOrStatus
      if (typeof address      === 'string') patchBody.MailingStreet = address

      if (Object.keys(patchBody).length === 0) return Response.json({ error: 'No fields to update' }, { status: 400 })

      const url = `${env.SALESFORCE_BASE_URL}/services/data/v66.0/sobjects/Contact/${encodeURIComponent(customerId)}`
      const sfRes = await fetch(url, {
        method: 'PATCH',
        headers: { 'Authorization': `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(patchBody)
      })

      if (!sfRes.ok) {
        const errorText = await sfRes.text()
        return Response.json({ error: 'Salesforce customer update failed', details: errorText }, { status: 500 })
      }
      return Response.json({ ok: true })
    }

    return Response.json({ error: `Unknown backend: ${config.backend}` }, { status: 500 })
  } catch (err) {
    return Response.json({ error: String(err?.message || err) }, { status: 500 })
  }
}

async function handleRecordUpdate(request, env) {
  try {
    if (request.method !== 'POST') return new Response('Method not allowed', { status: 405 })

    const config = await env.DB.prepare(`SELECT * FROM config WHERE id=1 LIMIT 1`).first()
    if (!config) return Response.json({ error: 'No config found' }, { status: 500 })

    const body     = await request.json().catch(() => ({}))
    const recordId = body.recordId
    const status   = body.status

    if (!recordId) return Response.json({ error: 'recordId is required' }, { status: 400 })
    if (!status)   return Response.json({ error: 'status is required' }, { status: 400 })

    if (config.backend === 'custom_crm') {
      const token    = env.MOCK_API_TOKEN
      const base     = env.MOCK_API_BASE_URL
      const patchUrl = `${base}/cases?token=${encodeURIComponent(token)}&id=${encodeURIComponent(recordId)}`

      const patchRes  = await fetch(patchUrl, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status })
      })
      const patchData = await patchRes.json().catch(() => ({}))

      if (!patchRes.ok) return Response.json({ error: 'Mock CRM update failed', details: patchData }, { status: 500 })
      return Response.json({ ok: true, updated: patchData })
    }

    if (config.backend === 'salesforce') {
      const accessToken = await getSalesforceAccessToken(env)
      const url = `${env.SALESFORCE_BASE_URL}/services/data/v66.0/sobjects/Case/${encodeURIComponent(recordId)}`

      const sfRes = await fetch(url, {
        method: 'PATCH',
        headers: { 'Authorization': `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ Status: status })
      })

      if (!sfRes.ok) {
        const errorText = await sfRes.text()
        return Response.json({ error: 'Salesforce case update failed', details: errorText }, { status: 500 })
      }
      return Response.json({ ok: true })
    }

    return Response.json({ error: `Unknown backend: ${config.backend}` }, { status: 500 })
  } catch (err) {
    return Response.json({ error: String(err?.message || err) }, { status: 500 })
  }
}

async function handleRecordCreate(request, env) {
  try {
    if (request.method !== 'POST') return new Response('Method not allowed', { status: 405 })

    const config = await env.DB.prepare(`SELECT * FROM config WHERE id=1 LIMIT 1`).first()
    if (!config) return Response.json({ error: 'No config found' }, { status: 500 })

    const body        = await request.json().catch(() => ({}))
    const phone       = normalizePhone(body.phone || '')
    const subject     = body.subject || ''
    const status      = body.status  || ''
    const description = body.description || ''

    if (!phone)   return Response.json({ error: 'phone is required' }, { status: 400 })
    if (!subject) return Response.json({ error: 'subject is required' }, { status: 400 })
    if (!status)  return Response.json({ error: 'status is required' }, { status: 400 })

    // In combination mode (or when the frontend specifies a CRM explicitly), honour targetBackend
    const effectiveBackend = body.targetBackend || config.backend

    if (effectiveBackend === 'custom_crm' || (effectiveBackend !== 'salesforce' && effectiveBackend !== 'hubspot')) {
      // ── any mock-backed CRM ──
      const token = env.MOCK_API_TOKEN
      const base  = env.MOCK_API_BASE_URL

      const existingRes  = await fetch(`${base}/cases?token=${encodeURIComponent(token)}`, { method: 'GET' })
      const existingRows = await existingRes.json().catch(() => [])
      const maxId = Array.isArray(existingRows)
        ? existingRows.reduce((m, row) => Math.max(m, Number(row.id || 0)), 0) : 0
      const nextId = maxId + 1

      const now      = new Date()
      const isoStamp = now.toISOString().slice(0, 16).replace('T', ' ')
      const payload  = {
        id: nextId,
        number: phone,
        status,
        subject,
        description,
        date: now.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' }),
        lastUpdate: isoStamp
      }

      const createRes  = await fetch(`${base}/cases?token=${encodeURIComponent(token)}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      })
      const createData = await createRes.json().catch(() => ({}))

      if (!createRes.ok) return Response.json({ error: 'Mock CRM create failed', details: createData }, { status: 500 })
      return Response.json({ ok: true, created: payload })
    }

    if (effectiveBackend === 'salesforce') {
      const accessToken = await getSalesforceAccessToken(env)

      // Prefer the contactId passed directly (e.g. after a picker selection),
      // fall back to phone lookup if not available
      let contactId = body.customerId || null
      if (!contactId) {
        const p             = escapeSoql(phone)
        const contactQuery  = `SELECT Id FROM Contact WHERE Phone='${p}' OR MobilePhone='${p}' LIMIT 1`
        const contactResult = await salesforceQuery(contactQuery, accessToken, env)
        const contactRow    = contactResult.records?.[0] || null
        if (!contactRow) return Response.json({ error: 'Contact not found for phone' }, { status: 404 })
        contactId = contactRow.Id
      }

      const casePayload = { ContactId: contactId, Subject: subject, Status: status, Description: description }
      const url = `${env.SALESFORCE_BASE_URL}/services/data/v66.0/sobjects/Case`

      const sfRes  = await fetch(url, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(casePayload)
      })
      const sfData = await sfRes.json().catch(() => ({}))

      if (!sfRes.ok) return Response.json({ error: 'Salesforce case create failed', details: sfData }, { status: 500 })
      return Response.json({ ok: true, created: sfData })
    }

    if (effectiveBackend === 'hubspot') {
      const hsToken   = env.HUBSPOT_TOKEN
      const hsHeaders = { 'Authorization': `Bearer ${hsToken}`, 'Content-Type': 'application/json' }

      // Find or use the contact id
      let contactId = body.customerId || null
      if (!contactId) {
        const searchPayload = {
          filterGroups: [
            { filters: [{ propertyName: 'phone',       operator: 'EQ', value: phone }] },
            { filters: [{ propertyName: 'mobilephone', operator: 'EQ', value: phone }] }
          ],
          properties: ['firstname', 'lastname'],
          limit: 1
        }
        const srRes  = await fetch('https://api.hubapi.com/crm/v3/objects/contacts/search', {
          method: 'POST', headers: hsHeaders, body: JSON.stringify(searchPayload)
        })
        const srData = await srRes.json().catch(() => ({}))
        contactId = srData.results?.[0]?.id || null
      }

      // Create ticket
      const ticketPayload = {
        properties: {
          subject:            subject,
          content:            description,
          hs_pipeline:        '0',
          hs_pipeline_stage:  '1',
          hs_ticket_priority: status === 'High' ? 'HIGH' : 'MEDIUM'
        }
      }
      const ticketRes  = await fetch('https://api.hubapi.com/crm/v3/objects/tickets', {
        method: 'POST', headers: hsHeaders, body: JSON.stringify(ticketPayload)
      })
      const ticketData = await ticketRes.json().catch(() => ({}))
      if (!ticketRes.ok) return Response.json({ error: 'HubSpot ticket create failed', details: ticketData }, { status: 500 })

      // Associate ticket → contact if we have one
      if (contactId) {
        await fetch(
          `https://api.hubapi.com/crm/v3/objects/tickets/${ticketData.id}/associations/contacts/${contactId}/ticket_to_contact`,
          { method: 'PUT', headers: hsHeaders, body: '{}' }
        ).catch(() => {})
      }

      return Response.json({ ok: true, created: ticketData })
    }

    return Response.json({ error: `Unknown backend: ${effectiveBackend}` }, { status: 500 })
  } catch (err) {
    return Response.json({ error: String(err?.message || err) }, { status: 500 })
  }
}

// ─────────────────────────────────────────
// API Handlers — Admin Seed / Reset
// ─────────────────────────────────────────

async function handleSeed(request, env) {
  try {
    const body        = await request.json()
    const scenarioKey = body.scenarioKey

    const seed = await env.DB.prepare(`SELECT * FROM seeds WHERE scenario_key=?`).bind(scenarioKey).first()
    if (!seed) return Response.json({ error: `Scenario not found: ${scenarioKey}` }, { status: 404 })

    // Derive the brand key: if the seed has a non-salesforce backend we use custom_crm preset,
    // but preserve whichever CRM is currently selected in config (don't change branding just from seeding)
    const currentConfig = await env.DB.prepare(`SELECT brand FROM config WHERE id=1 LIMIT 1`).first()
    const currentBrand  = currentConfig?.brand || 'custom_crm'

    // Only switch backend — keep the visual brand the user has selected
    const backendMap = { salesforce: 'salesforce' }
    const newBackend = backendMap[seed.backend] || 'custom_crm'

    await env.DB.prepare(`UPDATE config SET backend=?, updated_at=datetime('now') WHERE id=1`)
      .bind(newBackend).run()

    await env.DB.prepare(`UPDATE state SET value=? WHERE key='active_scenario'`)
      .bind(scenarioKey).run()

    return Response.json({ ok: true, scenarioKey, backend: newBackend, brand: currentBrand })
  } catch (err) {
    return Response.json({ error: String(err?.message || err) }, { status: 500 })
  }
}

async function handleResetAll(request, env) {
  try {
    const preset = getBrandPreset('custom_crm')
    await env.DB.prepare(`
      UPDATE config SET
        brand=?, backend=?, app_title=?, customer_label=?, primary_record_label=?,
        create_label=?, recent_records_label=?, customer_tier_label=?,
        logo_url=?, primary_hex=?, secondary_hex=?, accent_hex=?, updated_at=datetime('now')
      WHERE id=1
    `).bind(
      preset.brand, preset.backend, preset.app_title, preset.customer_label, preset.primary_record_label,
      preset.create_label, preset.recent_records_label, preset.customer_tier_label,
      preset.logo_url, preset.primary_hex, preset.secondary_hex, preset.accent_hex
    ).run()

    await env.DB.prepare(`UPDATE state SET value='custom_crm_appointment' WHERE key='active_scenario'`).run()

    return Response.json({ ok: true, brand: 'custom_crm' })
  } catch (err) {
    return Response.json({ error: String(err?.message || err) }, { status: 500 })
  }
}

// ─────────────────────────────────────────
// CRM Lookup Functions
// ─────────────────────────────────────────

// Route a lookup to the correct backend by brand key
function lookupForBrand(brandKey, { phone, email, env }) {
  if (brandKey === 'salesforce') return lookupSalesforce({ phone, email, env })
  if (brandKey === 'hubspot')    return lookupHubspot({ phone, email, env })
  return lookupMockCrm({ phone, email, env })
}

// ─────────────────────────────────────────
// HubSpot Lookup (real API, private app token)
// ─────────────────────────────────────────

async function lookupHubspot({ phone, email, env }) {
  const token = env.HUBSPOT_TOKEN
  if (!token) throw new Error('HUBSPOT_TOKEN secret not configured')

  const headers = {
    'Authorization': `Bearer ${token}`,
    'Content-Type': 'application/json'
  }

  // Search contacts by phone or mobilephone
  const searchPayload = {
    filterGroups: [
      { filters: [{ propertyName: 'phone',       operator: 'EQ', value: phone }] },
      { filters: [{ propertyName: 'mobilephone', operator: 'EQ', value: phone }] }
    ],
    properties: ['firstname', 'lastname', 'email', 'phone', 'mobilephone', 'company', 'lifecyclestage'],
    limit: 1
  }

  const searchRes  = await fetch('https://api.hubapi.com/crm/v3/objects/contacts/search', {
    method: 'POST',
    headers,
    body: JSON.stringify(searchPayload)
  })
  const searchData = await searchRes.json().catch(() => ({}))

  if (!searchData.total || searchData.total === 0) {
    return { customer: null, primaryRecord: null, recentRecords: [] }
  }

  const contact   = searchData.results[0]
  const contactId = contact.id
  const props     = contact.properties || {}
  const fullName  = `${props.firstname || ''} ${props.lastname || ''}`.trim() || 'Unknown Caller'

  const customer = {
    id:           contactId,
    name:         fullName,
    email:        props.email       || '',
    phone:        props.phone       || props.mobilephone || phone,
    address:      props.company     || '',
    tierOrStatus: props.lifecyclestage || ''
  }

  // Get associated ticket IDs
  const assocRes  = await fetch(
    `https://api.hubapi.com/crm/v3/objects/contacts/${contactId}/associations/tickets`,
    { headers }
  )
  const assocData  = await assocRes.json().catch(() => ({ results: [] }))
  const ticketIds  = (assocData.results || []).map(r => r.id).slice(0, 5)

  // Fetch ticket details in parallel
  const ticketDetails = await Promise.all(
    ticketIds.map(tid =>
      fetch(
        `https://api.hubapi.com/crm/v3/objects/tickets/${tid}?properties=subject,hs_pipeline_stage,hs_ticket_priority,content,createdate`,
        { headers }
      )
        .then(r => r.json())
        .catch(() => null)
    )
  )

  const tickets = ticketDetails
    .filter(Boolean)
    .map(t => {
      const tp = t.properties || {}
      return {
        id:            String(t.id),
        displayNumber: String(t.id),
        subject:       tp.subject || 'No subject',
        status:        tp.hs_pipeline_stage === '4' ? 'Closed' : 'Open',
        dueDate:       tp.createdate ? tp.createdate.split('T')[0] : '',
        description:   tp.content || '',
        lastUpdated:   '',
        caseUrl:       `https://app.hubspot.com/contacts/tickets/${t.id}`
      }
    })

  const openTickets   = tickets.filter(t => t.status !== 'Closed')
  const primaryRecord = openTickets.length ? openTickets[0] : (tickets.length ? tickets[0] : null)
  const recentRecords = tickets.filter(t => t !== primaryRecord).slice(0, 3)

  return { customer, primaryRecord, recentRecords }
}

async function lookupMockCrm({ phone, email, env }) {
  const token = env.MOCK_API_TOKEN
  const base  = env.MOCK_API_BASE_URL

  const [customerRes, casesRes] = await Promise.all([
    fetch(`${base}/demoapp?token=${encodeURIComponent(token)}&number=${encodeURIComponent(phone)}`),
    fetch(`${base}/cases?token=${encodeURIComponent(token)}&number=${encodeURIComponent(phone)}`)
  ])

  const customers = await customerRes.json()
  const cases     = await casesRes.json()

  const customer     = Array.isArray(customers) && customers.length ? mapMockCustomer(customers[0]) : null
  const mappedCases  = Array.isArray(cases) ? cases.map(mapMockCase) : []
  const primaryRecord = mappedCases.length ? mappedCases[0] : null
  const recentRecords = mappedCases.slice(1, 4)

  return { customer, primaryRecord, recentRecords }
}

function mapMockCustomer(row) {
  return {
    id:           String(row.id ?? ''),
    name:         row.name   || '',
    email:        row.email  || '',
    phone:        row.number || '',
    address:      row.location || '',
    tierOrStatus: row.status || ''
  }
}

function mapMockCase(row) {
  return {
    id:            String(row.id ?? ''),
    displayNumber: row.reference || row.ref || '',
    subject:       row.subject   || row.description || row.next || '',
    status:        row.status    || '',
    dueDate:       row.due       || row.date || '',
    description:   row.description || '',
    lastUpdated:   row.lastUpdate  || '',
    caseUrl:       ''
  }
}

async function lookupSalesforce({ phone, email, env }) {
  const accessToken = await getSalesforceAccessToken(env)
  const p = escapeSoql(phone)

  // Fetch up to 5 matches so we can offer a picker if there are duplicates
  const contactSoql = `SELECT Id,Name,Email,Phone,MobilePhone,MailingAddress,Status__c,LastModifiedDate FROM Contact WHERE Phone='${p}' OR MobilePhone='${p}' ORDER BY LastModifiedDate DESC LIMIT 5`
  const contactResult = await salesforceQuery(contactSoql, accessToken, env)
  const contactRows = Array.isArray(contactResult.records) ? contactResult.records : []

  if (contactRows.length === 0) return { customer: null, primaryRecord: null, recentRecords: [] }

  // Multiple matches — return list for the UI to present a picker
  if (contactRows.length > 1) {
    return {
      customer: null,
      primaryRecord: null,
      recentRecords: [],
      customerMatches: contactRows.map(mapSalesforceContact)
    }
  }

  // Single match — load records immediately as before
  return await lookupSalesforceByContactId({ contactId: contactRows[0].Id, accessToken, env })
}

async function lookupSalesforceByContactId({ contactId, accessToken, env }) {
  // Allow callers without an existing token to obtain one
  const token = accessToken || await getSalesforceAccessToken(env)
  const id    = escapeSoql(contactId)

  const contactSoql = `SELECT Id,Name,Email,Phone,MobilePhone,MailingAddress,Status__c,LastModifiedDate FROM Contact WHERE Id='${id}' LIMIT 1`
  const contactResult = await salesforceQuery(contactSoql, token, env)
  const contactRow    = contactResult.records?.[0] || null
  if (!contactRow) return { customer: null, primaryRecord: null, recentRecords: [] }

  const primarySoql = `SELECT Id,CaseNumber,Subject,Status,Description,Date__c,LastModifiedDate FROM Case WHERE ContactId='${id}' AND Status IN ('New','Open','Pending') ORDER BY LastModifiedDate DESC LIMIT 1`
  const recentSoql  = `SELECT Id,CaseNumber,Subject,Status,Description,Date__c,LastModifiedDate FROM Case WHERE ContactId='${id}' ORDER BY LastModifiedDate DESC LIMIT 3`

  const [primaryResult, recentResult] = await Promise.all([
    salesforceQuery(primarySoql, token, env),
    salesforceQuery(recentSoql,  token, env)
  ])

  return {
    customer:      mapSalesforceContact(contactRow),
    primaryRecord: primaryResult.records?.[0] ? mapSalesforceCase(primaryResult.records[0], env) : null,
    recentRecords: (recentResult.records || []).slice(0, 3).map(r => mapSalesforceCase(r, env))
  }
}

function mapSalesforceContact(row) {
  return {
    id:           String(row.Id ?? ''),
    name:         row.Name     || '',
    email:        row.Email    || '',
    phone:        row.Phone    || '',
    address:      formatSalesforceAddress(row.MailingAddress),
    tierOrStatus: row.Status__c || ''
  }
}

function mapSalesforceCase(row, env) {
  return {
    id:            String(row.Id ?? ''),
    displayNumber: row.CaseNumber || '',
    subject:       row.Subject    || '',
    status:        row.Status     || '',
    dueDate:       row.Date__c    || '',
    description:   row.Description || '',
    lastUpdated:   row.LastModifiedDate || '',
    caseUrl:       `${env.SALESFORCE_BASE_URL}/${row.Id}`
  }
}

function formatSalesforceAddress(addr) {
  if (!addr || typeof addr !== 'object') return ''
  return [addr.street, addr.city, addr.state, addr.postalCode, addr.country].filter(Boolean).join(', ')
}

async function getSalesforceAccessToken(env) {
  const body = new URLSearchParams({
    grant_type:    'client_credentials',
    client_id:     env.SALESFORCE_CLIENT_ID,
    client_secret: env.SALESFORCE_CLIENT_SECRET
  })

  const res  = await fetch(env.SALESFORCE_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: body.toString()
  })
  const data = await res.json().catch(() => ({}))

  if (!res.ok || !data.access_token) throw new Error(`Salesforce token failed: ${JSON.stringify(data)}`)
  return data.access_token
}

async function salesforceQuery(soql, accessToken, env) {
  const url  = `${env.SALESFORCE_BASE_URL}/services/data/v66.0/query?q=${encodeURIComponent(soql)}`
  const res  = await fetch(url, { headers: { 'Authorization': `Bearer ${accessToken}` } })
  const data = await res.json().catch(() => ({}))

  if (!res.ok) throw new Error(`Salesforce query failed: ${JSON.stringify(data)}`)
  return data
}
